{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

arguments.content:
{
  "watch1": {
    "scenarios": [
      "features/todo-management.feature:Adding a new todo creates an item in the list",
      "features/todo-management.feature:Main and footer are hidden when there are no todos",
      "features/todo-management.feature:Main and footer are shown when a todo exists",
      "features/todo-management.feature:Toggling a todo marks it as completed",
      "features/todo-management.feature:Toggling a completed todo marks it as active",
      "features/todo-management.feature:Deleting a todo removes it from the list",
      "features/todo-management.feature:Active item count displays correctly",
      "features/todo-management.feature:Active item count is pluralized",
      "features/todo-management.feature:Empty input is ignored on Enter"
    ]
  },
  "watch2": {
    "scenarios": [
      "features/todo-management.feature:Marking all todos as complete",
      "features/todo-management.feature:Clearing all completed todos",
      "features/todo-management.feature:Clear completed button is hidden when no todos are completed",
      "features/todo-management.feature:Clear completed button is visible when a todo is completed"
    ]
  },
  "watch3": {
    "scenarios": [
      "features/persistence.feature:Todos persist after page reload",
      "features/persistence.feature:Completed state persists after page reload",
      "features/persistence.feature:Editing mode is not persisted after page reload",
      "features/persistence.feature:Active filter selection persists after page reload"
    ]
  },
  "watch4": {
    "scenarios": [
      "features/todo-editing.feature:Double-clicking a todo label activates editing mode",
      "features/todo-editing.feature:Saving an edit on Enter key",
      "features/todo-editing.feature:Saving an edit on blur",
      "features/todo-editing.feature:Empty edit destroys the todo",
      "features/todo-editing.feature:Whitespace-only edit destroys the todo",
      "features/todo-editing.feature:Escape key cancels editing and restores original title"
    ]
  },
  "watch5": {
    "scenarios": [
      "features/routing.feature:Default route shows all todos",
      "features/routing.feature:Active filter shows only active todos",
      "features/routing.feature:Completed filter shows only completed todos",
      "features/routing.feature:All filter shows all todos",
      "features/routing.feature:Completing a todo hides it in active filter"
    ]
  }
}
